if (msg.req.files && msg.req.files.length > 0) {
    var file = msg.req.files[0];

    // 1. Extraer ID del miembro y Session ID
    // El ID debe venir en el multipart con key 'id'
    msg.member_id = (msg.req.body && msg.req.body.id) ? msg.req.body.id : null;
    msg.session_id = msg.req.headers['x-session-id'];

    // VALIDACIONES
    if (!msg.member_id) {
        msg.payload = { error: "Missing member 'id' in multipart body" };
        msg.statusCode = 400;
        return [null, msg]; // Salida 2: Error
    }
    if (!msg.session_id) {
        msg.payload = { error: "Missing 'X-Session-Id' header" };
        msg.statusCode = 400;
        return [null, msg]; // Salida 2: Error
    }

    // Guardar imagen original
    msg.original_image_data = {
        buffer: file.buffer,
        filename: file.originalname,
        mimetype: file.mimetype
    };

    msg.payload = {
        "image": {
            "value": file.buffer,
            "options": {
                "filename": file.originalname,
                "contentType": file.mimetype
            }
        }
    };
    msg.headers = {};
    msg.headers['content-type'] = 'multipart/form-data';
} else {
    msg.payload = { error: "No file uploaded" };
    msg.statusCode = 400;
    return [null, msg];
}
return [msg, null]; // Salida 1: Éxito

const TH = 0.5;
const p = msg.payload || {};
const score = Number(p.score);

if (Number.isNaN(score) || score < TH) {
    msg.payload = { error: 'No valid face detected (score < 0.5)' };
    msg.statusCode = 400;
    return [null, msg]; 
}

// Si hay cara, seguimos a Uniface
return [msg, null];

if (msg.original_image_data) {
    msg.payload = {
        "image": {
            "value": msg.original_image_data.buffer,
            "options": {
                "filename": msg.original_image_data.filename,
                "contentType": msg.original_image_data.mimetype
            }
        }
    };
    msg.headers = {};
    msg.headers['content-type'] = 'multipart/form-data';
} else {
   msg.payload = {};
}
return msg;

const resp = msg.payload || {};

// 1. Verificar si Uniface reconoció algo
if (resp.recognized === false) {
    msg.payload = { error: 'No face generated by Uniface', reason: resp.reason || 'unknown' };
    msg.statusCode = 400;
    return [null, msg]; // Opción error
}

if (!resp.embedding || !Array.isArray(resp.embedding)) {
    msg.payload = { error: 'No embedding generated (unexpected)' };
    msg.statusCode = 500;
    return [null, msg];
}

// Convertir a Base64
const floatArray = new Float32Array(resp.embedding);
const buffer = Buffer.from(floatArray.buffer);
const embeddingBase64 = buffer.toString('base64');

// Configurar petición REST
msg.url = `http://localhost:8080/member/${msg.member_id}/embedding`;
// El método PUT se configura en el siguiente nodo
msg.headers = {};
msg.headers['Content-Type'] = 'application/json';
if (msg.session_id) {
    msg.headers['X-Session-Id'] = msg.session_id;
}

// Body (coincide con SetEmbeddingRequest de Java)
msg.payload = {
    embeddingBase64: embeddingBase64
};

return [msg, null];

msg.payload = { error: msg.payload.error || msg.error || 'Unknown error' };
// Mantener status si existe, o 400 por defecto
msg.statusCode = msg.statusCode || 400;
return msg;
